-- Zernio Phase 9 Enterprise foundation. Safe to retry.
begin; set local lock_timeout='20s';

create or replace function public.current_staff_id() returns bigint language sql stable security definer set search_path=public as $$select id from public.staff where lower(email)=lower(coalesce(auth.jwt()->>'email','')) and is_active limit 1$$;
create or replace function public.current_clinic_id() returns bigint language sql stable security definer set search_path=public as $$select clinic_id from public.staff where id=public.current_staff_id()$$;
create or replace function public.current_branch_id() returns bigint language sql stable security definer set search_path=public as $$select branch_id from public.staff where id=public.current_staff_id()$$;
create or replace function public.has_hr_permission(permission_code text) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.hr_staff_roles sr join public.hr_role_permissions rp on rp.role_id=sr.role_id join public.hr_permissions p on p.id=rp.permission_id where sr.staff_id=public.current_staff_id() and p.code=permission_code)$$;

create table if not exists public.enterprise_audit_log(id bigint generated by default as identity primary key,clinic_id bigint references public.clinics(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,actor_staff_id bigint references public.staff(id) on delete set null,action text not null,entity_type text not null,entity_id text,summary text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.enterprise_notifications(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id) on delete cascade,branch_id bigint references public.branches(id) on delete cascade,recipient_staff_id bigint references public.staff(id) on delete cascade,title text not null,message text not null,type text not null default 'info',href text,is_read boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.enterprise_tasks(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id) on delete cascade,branch_id bigint references public.branches(id) on delete cascade,title text not null,description text,assigned_to bigint references public.staff(id) on delete set null,created_by bigint references public.staff(id) on delete set null,status text not null default 'todo' check(status in('todo','in_progress','completed','cancelled')),priority text not null default 'medium' check(priority in('low','medium','high','urgent')),due_at timestamptz,source_type text,source_id text,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.enterprise_workflows(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id) on delete cascade,branch_id bigint references public.branches(id) on delete cascade,name text not null,trigger_event text not null check(trigger_event in('appointment_booked','appointment_no_show','treatment_completed','payment_outstanding','lead_created','stock_low')),action_type text not null check(action_type in('create_task','create_notification','queue_follow_up')),action_config jsonb not null default '{}'::jsonb,is_active boolean not null default true,created_at timestamptz not null default now(),unique(clinic_id,branch_id,name));
create table if not exists public.enterprise_workflow_runs(id bigint generated by default as identity primary key,workflow_id bigint not null references public.enterprise_workflows(id) on delete cascade,clinic_id bigint not null references public.clinics(id) on delete cascade,branch_id bigint references public.branches(id) on delete cascade,event_type text not null,entity_id text,status text not null default 'completed',details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.enterprise_preferences(staff_id bigint primary key references public.staff(id) on delete cascade,clinic_id bigint not null references public.clinics(id) on delete cascade,language text not null default 'en' check(language in('en','ar')),timezone text not null default 'Asia/Riyadh',updated_at timestamptz not null default now());

insert into public.hr_permissions(code,name,module) values('enterprise.manage','Manage enterprise workflows','Enterprise'),('audit.view','View audit log','Enterprise'),('tasks.manage','Manage clinic tasks','Enterprise') on conflict(code) do update set name=excluded.name,module=excluded.module;
insert into public.hr_role_permissions(role_id,permission_id) select r.id,p.id from public.hr_roles r cross join public.hr_permissions p where r.name='Admin' and p.code in('enterprise.manage','audit.view','tasks.manage') on conflict do nothing;
insert into public.hr_role_permissions(role_id,permission_id) select r.id,p.id from public.hr_roles r cross join public.hr_permissions p where r.name in('Coordinator','Reception') and p.code='tasks.manage' on conflict do nothing;

alter table public.enterprise_audit_log enable row level security;alter table public.enterprise_notifications enable row level security;alter table public.enterprise_tasks enable row level security;alter table public.enterprise_workflows enable row level security;alter table public.enterprise_workflow_runs enable row level security;alter table public.enterprise_preferences enable row level security;
drop policy if exists enterprise_audit_read on public.enterprise_audit_log;create policy enterprise_audit_read on public.enterprise_audit_log for select to authenticated using(clinic_id=public.current_clinic_id() and public.has_hr_permission('audit.view'));
drop policy if exists enterprise_notifications_access on public.enterprise_notifications;create policy enterprise_notifications_access on public.enterprise_notifications for all to authenticated using(clinic_id=public.current_clinic_id() and (recipient_staff_id is null or recipient_staff_id=public.current_staff_id())) with check(clinic_id=public.current_clinic_id());
drop policy if exists enterprise_tasks_access on public.enterprise_tasks;create policy enterprise_tasks_access on public.enterprise_tasks for all to authenticated using(clinic_id=public.current_clinic_id() and (assigned_to=public.current_staff_id() or public.has_hr_permission('tasks.manage'))) with check(clinic_id=public.current_clinic_id() and public.has_hr_permission('tasks.manage'));
drop policy if exists enterprise_workflows_access on public.enterprise_workflows;create policy enterprise_workflows_access on public.enterprise_workflows for all to authenticated using(clinic_id=public.current_clinic_id() and public.has_hr_permission('enterprise.manage')) with check(clinic_id=public.current_clinic_id() and public.has_hr_permission('enterprise.manage'));
drop policy if exists enterprise_runs_read on public.enterprise_workflow_runs;create policy enterprise_runs_read on public.enterprise_workflow_runs for select to authenticated using(clinic_id=public.current_clinic_id() and public.has_hr_permission('enterprise.manage'));
drop policy if exists enterprise_preferences_access on public.enterprise_preferences;create policy enterprise_preferences_access on public.enterprise_preferences for all to authenticated using(staff_id=public.current_staff_id()) with check(staff_id=public.current_staff_id() and clinic_id=public.current_clinic_id());

create or replace function public.enterprise_audit_trigger() returns trigger language plpgsql security definer set search_path=public as $$declare row_data jsonb;cid bigint;bid bigint;eid text;begin row_data:=case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;cid:=coalesce((row_data->>'clinic_id')::bigint,public.current_clinic_id());bid:=nullif(row_data->>'branch_id','')::bigint;eid:=row_data->>'id';insert into public.enterprise_audit_log(clinic_id,branch_id,actor_staff_id,action,entity_type,entity_id,summary)values(cid,bid,public.current_staff_id(),lower(tg_op),tg_table_name,eid,tg_op||' on '||tg_table_name);return case when tg_op='DELETE' then old else new end;end$$;
do $$declare t text;begin foreach t in array array['customers','appointments','treatments','payments','inventory_products','staff','marketing_campaigns','marketing_leads'] loop execute format('drop trigger if exists enterprise_audit_%1$s on public.%1$I',t);execute format('create trigger enterprise_audit_%1$s after insert or update or delete on public.%1$I for each row execute function public.enterprise_audit_trigger()',t);end loop;end$$;

create or replace function public.run_enterprise_workflows() returns trigger language plpgsql security definer set search_path=public as $$declare w record;event_name text;row_data jsonb;begin row_data:=to_jsonb(new);event_name:=case when tg_table_name='appointments' and new.status='no_show' then 'appointment_no_show' when tg_table_name='appointments' and tg_op='INSERT' then 'appointment_booked' when tg_table_name='treatment_sessions' and new.status='completed' then 'treatment_completed' when tg_table_name='marketing_leads' and tg_op='INSERT' then 'lead_created' else null end;if event_name is null then return new;end if;for w in select * from public.enterprise_workflows where clinic_id=(row_data->>'clinic_id')::bigint and (branch_id is null or branch_id=(row_data->>'branch_id')::bigint) and trigger_event=event_name and is_active loop if w.action_type='create_task' then insert into public.enterprise_tasks(clinic_id,branch_id,title,description,priority,source_type,source_id,created_by)values(w.clinic_id,w.branch_id,coalesce(w.action_config->>'title',w.name),w.action_config->>'description',coalesce(w.action_config->>'priority','medium'),tg_table_name,row_data->>'id',public.current_staff_id());elsif w.action_type='create_notification' then insert into public.enterprise_notifications(clinic_id,branch_id,title,message,type,href)values(w.clinic_id,w.branch_id,coalesce(w.action_config->>'title',w.name),coalesce(w.action_config->>'message',event_name),'workflow',w.action_config->>'href');end if;insert into public.enterprise_workflow_runs(workflow_id,clinic_id,branch_id,event_type,entity_id)values(w.id,w.clinic_id,w.branch_id,event_name,row_data->>'id');end loop;return new;end$$;
drop trigger if exists enterprise_workflow_appointments on public.appointments;create trigger enterprise_workflow_appointments after insert or update of status on public.appointments for each row execute function public.run_enterprise_workflows();
drop trigger if exists enterprise_workflow_treatments on public.treatment_sessions;create trigger enterprise_workflow_treatments after update of status on public.treatment_sessions for each row execute function public.run_enterprise_workflows();
drop trigger if exists enterprise_workflow_leads on public.marketing_leads;create trigger enterprise_workflow_leads after insert on public.marketing_leads for each row execute function public.run_enterprise_workflows();

create index if not exists enterprise_tasks_scope_idx on public.enterprise_tasks(clinic_id,branch_id,status,due_at);create index if not exists enterprise_notifications_recipient_idx on public.enterprise_notifications(recipient_staff_id,is_read,created_at desc);create index if not exists enterprise_audit_scope_idx on public.enterprise_audit_log(clinic_id,created_at desc);
commit;select 'enterprise_phase9_ready' status;
